import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the Simple Moving Average (SMA) of the last 15 closing prices
    sma_15 = df['close'].rolling(window=15).mean()

    # Initialize the signals series with 0
    signals = pd.Series(0, index=df.index)

    # Determine the signals based on the conditions
    for i in range(len(df)):
        if i < 14:
            # Warm-up period
            signals[i] = 0
        else:
            if df['close'].iloc[i] > sma_15.iloc[i]:
                signals[i] = 1
            elif df['close'].iloc[i] < sma_15.iloc[i]:
                signals[i] = -1

    return signals
