import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate RSI(21)
    def rsi(data, n=21):
        avg_gain = data['close'].rolling(window=n).mean()
        avg_loss = data['close'].rolling(window=n).mean()
        rsi_values = 100 - 100 / (1 + avg_gain / avg_loss)
        rsi_values[rsi_values.isnull()] = 100
        return rsi_values

    # Initialize the position series
    position = pd.Series(0, index=df.index)

    # Calculate the RSI(21)
    rsi_values = rsi(df['close'])

    # Iterate over each bar to determine the position
    for i in range(len(df)):
        if position[i-1] == 0:
            # Flat
            if rsi_values[i] > 65:
                position[i] = -1
            elif rsi_values[i] < 35:
                position[i] = 1
            else:
                position[i] = 0
        else:
            # Long
            if rsi_values[i] > 52:
                position[i] = 0
            else:
                position[i] = position[i-1]
        # Short
        if rsi_values[i] < 52:
            position[i] = 0
        else:
            position[i] = position[i-1]

    return position
