import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the SMA and PSTD for the last 30 bars
    df['SMA_30'] = df['close'].rolling(window=30).mean()
    df['PSTD_30'] = df['close'].rolling(window=30).std()

    # Initialize the position series with 0
    position = pd.Series(0, index=df.index)

    # Calculate the upper and lower bands
    upper = df['SMA_30'] + 1.75 * df['PSTD_30']
    lower = df['SMA_30'] - 1.75 * df['PSTD_30']

    # Iterate over the DataFrame to generate signals
    for i in range(len(df)):
        if i < 29:
            # Warm-up period
            position[i] = 0
        else:
            # Apply the strategy
            if position[i-1] == 0:
                # Flat
                if df['close'].iloc[i] > upper.iloc[i-1]:
                    position[i] = 1
                else:
                    position[i] = 0
            else:
                # Long
                if df['close'].iloc[i] <= df['SMA_30'].iloc[i-1]:
                    position[i] = 0
                else:
                    position[i] = position[i-1]

    return position
